<?php

namespace Database\Seeders;

use Illuminate\Database\Seeder;

/**
 * Full development dataset.
 *
 * Model events are intentionally left ENABLED (no WithoutModelEvents): slugs are
 * generated by a model "saving" hook.
 *
 * In production run only: php artisan db:seed --class=RolesAndPermissionsSeeder
 */
class DatabaseSeeder extends Seeder
{
    public function run(): void
    {
        $this->call([
            RolesAndPermissionsSeeder::class,
            UserSeeder::class,
            CatalogSeeder::class,
            CouponSeeder::class,
            OrderSeeder::class,
            ReviewSeeder::class,
        ]);
    }
}
